 function Questions(){let list=s.questions.filter(x=>(!q||x.question.includes(q))&&(!filter.subject||x.subjectId===filter.subject)&&(!filter.difficulty||x.difficulty===filter.difficulty));return <section><Title title="بنك الأسئلة" sub="أسئلتك أنت فقط — لا يتم توليد أي سؤال." action={<button className="primary" onClick={()=>setModal('question')}><Plus/> سؤال</button>}/><div className="filterrow"><FilterBar subject={filter.subject} onSubject={v=>setFilter({...filter,subject:v})}/><select value={filter.difficulty} onChange={e=>setFilter({...filter,difficulty:e.target.value})}><option value="">كل الصعوبات</option><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select></div><div className="card">{list.length?list.map(x=><div className="listrow" key={x.id}><div><b>{x.question}</b><span>{subMap[x.subjectId]?.name||''} • {x.difficulty} • {x.type}</span></div><button aria-label="حذف السؤال" onClick={()=>update({questions:s.questions.filter(y=>y.id!==x.id)})}><Trash2/></button></div>):<Empty text="لسه مفيش أسئلة." action="أضف أول سؤال" onClick={()=>setModal('question')}/>}</div><button className="primary quizbtn" onClick={startQuiz}>اختبار سريع</button>{quiz.length>0&&!quizDone&&<Quiz/>}{quizDone&&<div className="card quizresult"><h2>النتيجة: {quizScore}/{quiz.length}</h2><p className="muted">تم تسجيل الأخطاء التي اخترت أنك أخطأت فيها.</p><button onClick={()=>{setQuizDone(false);setQuiz([])}}>إغلاق</button></div>}</section>}
 function startQuiz(){const pool=[...s.questions].filter(x=>(!filter.subject||x.subjectId===filter.subject)&&(!filter.difficulty||x.difficulty===filter.difficulty)).sort(()=>Math.random()-.5).slice(0,Math.min(10,s.questions.length));if(!pool.length){notify('أضف أسئلة أولًا');return}setQuiz(pool);setQuizIndex(0);setQuizScore(0);setQuizDone(false)}
